async def act(page):
    import asyncio
    import csv
    import io
    import re
    from datetime import datetime

    # Reasoning about KB functions:
    # - export_orders_csv / extract_last_orders_csv operate on the Dashboard "Last Orders" widget
    #   and only return a small recent snapshot; they cannot provide a full historical orders export
    #   needed to determine the customer with the most cancellations in history.
    # - export_customers_csv_via_grid exports Customers grid (not Orders) and is not applicable.
    # Therefore we must export the Orders grid from Sales > Orders. There is no KB helper for that,
    # so we will navigate to the Orders grid and use the grid's Export controls.

    # Navigate to the Orders grid page (relative goto as requested)
    await page.goto('/index.php/admin/sales_order/')
    # give the grid a moment to render
    await asyncio.sleep(1)

    # Try to locate an Export combobox scoped to a toolbar cell that mentions "Export to"
    export_combobox = None
    export_cell = None
    cells = page.get_by_role("cell").filter(has_text="Export to")
    if await cells.count() > 0:
        export_cell = cells.nth(0)
        # combobox is expected to be a native <select>
        try:
            if await export_cell.get_by_role("combobox").count() > 0:
                export_combobox = export_cell.get_by_role("combobox").nth(0)
        except Exception:
            export_combobox = None

    # Fallback: scan page comboboxes
    if export_combobox is None:
        comboboxes = page.get_by_role("combobox")
        if await comboboxes.count() > 0:
            export_combobox = comboboxes.nth(0)

    # Attempt to select CSV option
    if export_combobox is not None:
        # First try exact label
        try:
            await export_combobox.select_option(label="CSV")
        except Exception:
            # fallback: inspect option labels exposed as role='option'
            try:
                if await export_combobox.get_by_role("option").count() > 0:
                    opts = await export_combobox.get_by_role("option").all_inner_texts()
                    found_label = None
                    for o in opts:
                        if 'csv' in (o or '').lower():
                            found_label = o
                            break
                    if found_label is not None:
                        await export_combobox.select_option(label=found_label)
            except Exception:
                # last resort: try selecting by a common value
                try:
                    await export_combobox.select_option(value='csv')
                except Exception:
                    pass

    # Find an Export button scoped to the same cell if possible
    export_button = None
    if export_cell is not None:
        try:
            if await export_cell.get_by_role("button", name="Export").count() > 0:
                export_button = export_cell.get_by_role("button", name="Export").nth(0)
        except Exception:
            export_button = None

    if export_button is None:
        # fallback to any button that contains 'Export'
        btns = page.get_by_role("button").filter(has_text="Export")
        if await btns.count() > 0:
            export_button = btns.nth(0)

    if export_button is None:
        raise RuntimeError("Could not find an Export button on the Orders grid page")

    # Click Export and capture the download
    download_ctx = page.expect_download()
    await export_button.click()
    dl = await download_ctx
    filename = 'orders_export.csv'
    await dl.save_as(filename)

    # Read and decode the downloaded CSV
    with open(filename, 'rb') as f:
        data = f.read()
    try:
        text = data.decode('utf-8')
    except Exception:
        text = data.decode('latin-1')

    # Parse CSV into rows
    reader = csv.reader(io.StringIO(text))
    rows = list(reader)
    if not rows:
        raise RuntimeError('Exported CSV is empty')

    headers = [h.strip() for h in rows[0]]

    # helper to find column index by candidate substrings
    def find_col(candidates):
        for i, h in enumerate(headers):
            hl = h.lower()
            for c in candidates:
                if c in hl:
                    return i
        return None

    status_idx = find_col(['status', 'state'])
    customer_idx = find_col(['customer', 'billing name', 'billing_name', 'customer name', 'buyer'])
    date_idx = find_col(['created', 'created at', 'order date', 'date'])
    grand_idx = find_col(['grand total', 'grand_total', 'order total', 'total'])

    # Build list of dict rows
    data_rows = []
    for r in rows[1:]:
        if len(r) < len(headers):
            r = r + [''] * (len(headers) - len(r))
        data_rows.append({headers[i]: r[i].strip() for i in range(len(headers))})

    # Filter cancelled orders (match 'cancel' substring in status)
    cancelled = []
    for r in data_rows:
        status_val = ''
        if status_idx is not None and status_idx < len(headers):
            status_val = r[headers[status_idx]]
        if 'cancel' in (status_val or '').lower():
            # determine customer identifier value
            cust_val = ''
            if customer_idx is not None and customer_idx < len(headers):
                cust_val = r[headers[customer_idx]]
            # fallback to email if customer name not present
            if not cust_val:
                # try to find an email-like column
                for h in headers:
                    if 'email' in h.lower():
                        cust_val = r[h]
                        break
            cancelled.append({'row': r, 'customer': cust_val})

    if not cancelled:
        # no cancelled orders found - return 0.00
        result_str = "0.00"
        print(result_str)
        return

    # Count cancellations per customer
    counts = {}
    for c in cancelled:
        key = c['customer'] or '(guest)'
        counts[key] = counts.get(key, 0) + 1

    # Customer with the most cancellations (tie -> choose lexicographically first)
    max_count = max(counts.values())
    candidates = [k for k, v in counts.items() if v == max_count]
    max_customer = sorted(candidates)[0]

    # Filter cancelled orders for that customer
    cust_cancelled_rows = [c['row'] for c in cancelled if (c['customer'] or '(guest)') == max_customer]

    # Parse dates for those orders
    def parse_date(val):
        if not val:
            return None
        val = val.strip()
        fmts = ["%Y-%m-%d %H:%M:%S", "%Y-%m-%d", "%m/%d/%Y %H:%M:%S", "%m/%d/%Y", "%d/%m/%Y %H:%M:%S", "%d/%m/%Y"]
        for f in fmts:
            try:
                return datetime.strptime(val, f)
            except Exception:
                pass
        try:
            return datetime.fromisoformat(val.replace(' ', 'T'))
        except Exception:
            return None

    dated = []
    for r in cust_cancelled_rows:
        date_val = ''
        if date_idx is not None and date_idx < len(headers):
            date_val = r[headers[date_idx]]
        parsed = parse_date(date_val)
        dated.append((parsed, r))

    # Determine the most recent timestamp among parsed dates; if none parsed, use last row
    dated_with = [d for d in dated if d[0] is not None]
    if dated_with:
        dated_with.sort(key=lambda x: x[0], reverse=True)
        most_recent_ts = dated_with[0][0]
        # select all rows that match that timestamp (to handle multiple orders at same most-recent time)
        most_recent_rows = [r for p, r in dated_with if p == most_recent_ts]
    else:
        # fallback: treat the last row in cust_cancelled_rows as the most recent
        most_recent_rows = [cust_cancelled_rows[-1]]

    # Helper to parse currency/number from a string
    def parse_money(s):
        if not s:
            return 0.0
        s = s.strip()
        # remove common currency symbols
        s = s.replace('$', '').replace('€', '').replace('£', '')
        # remove commas
        s = s.replace(',', '')
        # find first number pattern
        m = re.search(r"-?[0-9]+(?:\.[0-9]+)?", s)
        if not m:
            return 0.0
        try:
            return float(m.group(0))
        except Exception:
            return 0.0

    # Sum grand totals for the most recent cancelled order(s)
    total_spend = 0.0
    for r in most_recent_rows:
        value = 0.0
        if grand_idx is not None and grand_idx < len(headers):
            raw = r[headers[grand_idx]]
            value = parse_money(raw)
        else:
            # fallback: try find any header containing 'total'
            guessed = None
            for h in headers:
                if 'total' in h.lower():
                    guessed = r[h]
                    break
            if guessed:
                value = parse_money(guessed)
        total_spend += value

    result_str = f"{total_spend:.2f}"
    # Print only the numeric result as required
    print(result_str)

