    await asyncio.sleep(1)

    # Try to locate an Export combobox scoped to a toolbar cell that mentions "Export to"
    export_combobox = None
    export_cell = None
    cells = page.get_by_role("cell").filter(has_text="Export to")
    if await cells.count() > 0:
        export_cell = cells.nth(0)
        # combobox is expected to be a native <select>
        try:
            if await export_cell.get_by_role("combobox").count() > 0:
                export_combobox = export_cell.get_by_role("combobox").nth(0)
        except Exception:
            export_combobox = None

    # Fallback: scan page comboboxes
    if export_combobox is None:
        comboboxes = page.get_by_role("combobox")
        if await comboboxes.count() > 0:
            export_combobox = comboboxes.nth(0)

    # Attempt to select CSV option
    if export_combobox is not None:
        # First try exact label
        try:
            await export_combobox.select_option(label="CSV")
        except Exception:
            # fallback: inspect option labels exposed as role='option'
            try:
                if await export_combobox.get_by_role("option").count() > 0:
                    opts = await export_combobox.get_by_role("option").all_inner_texts()
                    found_label = None
                    for o in opts:
                        if 'csv' in (o or '').lower():
                            found_label = o
                            break
                    if found_label is not None:
                        await export_combobox.select_option(label=found_label)
            except Exception:
                # last resort: try selecting by a common value
                try:
                    await export_combobox.select_option(value='csv')
                except Exception:
                    pass

